```cpp
#include <boost/markdown.hpp>
#include <string>

std::string markdown_to_html(const std::string& markdown_input) {
    boost::markdown::parser parser;
    std::string html_output;
    parser.parse(markdown_input, html_output);
    return html_output;
}
```

