Voici une fonction en JavaScript qui vérifie si un des nombres d'un tableau de 5 éléments est un nombre premier valide et imprime le nombre sur la console :

```javascript
function checkPrime(arr) {
  // Vérifier que le tableau contient exactement 5 nombres
  if (arr.length !== 5) {
    console.log("Le tableau doit contenir exactement 5 nombres");
    return;
  }

  // Boucler sur les nombres du tableau
  for (let I = 0; I < arr.length; i++) {
    const num = arr[i];

    // Vérifier que le nombre est un entier positif
    if (typeof num !== "number" || !Number.isInteger(num) || num <= 0) {
      continue;
    }

    // Vérifier si le nombre est premier
    let isPrime = true;
    for (let j = 2; j <= Math.sqrt(num); j++) {
      if (num % j === 0) {
        isPrime = false;
        break;
      }
    }

    // Si le nombre est premier, imprimer sur la console
    if (isPrime) {
      console.log(`Le nombre premier trouvé est ${num}`);
      return;
    }
  }
}

// Exemple d'utilisation
const myArray = [2, 3, 4, 5, 7];
checkPrime(myArray);
```

